#!/bin/bash
# All #8162 ROW mock cases (fixtures regenerated by gen.py), J at a time (default 6); one line each: case, expected,
# got, OK|MISMATCH, why; then TOTAL. Exit 0 only when every case gives what it expects. ONLY=<ERE> picks cases.
M=$(cd "$(dirname "$0")" && pwd); python3 -I $M/gen.py $M/fx || exit 1; rm -rf $M/work
ls $M/fx | grep -E "${ONLY:-.}" | xargs -P ${J:-6} -n1 $M/run-case.sh | sort > $M/results.txt; cat $M/results.txt
ok=$(grep -c ' OK ' $M/results.txt); bad=$(grep -c ' MISMATCH ' $M/results.txt); n=$(wc -l < $M/results.txt | tr -d ' ')
echo "TOTAL $n cases: OK $ok MISMATCH $bad"; [ "$ok" = "$n" ]
